// Placeholder JobRankingAgent
// Reads jobs from input and adds a mock score for each job.
const jobs = $json["jobs"] || [];
const scored = jobs.map((j, i) => ({ company: j.company, role: j.role, score: 100 - i }));
return { ranked_jobs: scored };

// OutreachEmailAgent placeholder
// Picks the top ranked job and makes a simple email draft.
const top = ($json["ranked_jobs"] || [])[0] || { company: "NoCompany", role: "NoRole" };
const draft = {
  drafts: [
    {
      company: top.company,
      role: top.role,
      subject: `Quick question about ${top.company}`,
      body: `Hi ${top.company},\n\nI noticed your work on ${top.role} and I thought I'd reach out. I built similar projects and would love to chat about opportunities.\n\nBest,\nKrish`
    }
  ]
};
return draft;

// ChatbotRefinementAgent placeholder
// Takes the email draft and "refines" it by adding more human-like phrasing.

const draft = ($json["drafts"] || [])[0] || {};

const refined = {
  refined_email: {
    company: draft.company || "",
    role: draft.role || "",
    subject: draft.subject ? draft.subject + " (refined)" : "",
    body: draft.body
      ? draft.body + "\n\n(Refined by AI to sound more natural and friendly.)"
      : ""
  }
};

return refined;

// Logging/EvaluationAgent placeholder
// Creates a small log object showing the workflow ran and what came in.

return {
  log: "Workflow executed successfully",
  timestamp: new Date().toISOString(),
  debug_input: $input.all()  // shows all inputs received by this node
};

// ResumeParsingAgent placeholder
return {
  parsed_resume: {
    name: "AgentM",
    top_bullets: [
      "Built feature X in 3 months",
      "Improved performance by 30%"
    ]
  }
};

// Simulate API response and return clean jobs object
return {
  jobs: [
    { company: "ABC Corp", role: "Developer" },
    { company: "Example Labs", role: "Backend Engineer" }
  ],
  source: {
    url: $json["simulated_api_url"] || "https://example.com/api/jobs"
  }
};
